import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第一章 一般规定","description":"","frontmatter":{"title":"第一章 一般规定","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/diyifenbian：tongze（diyizhang：yibanguiding）（hetong）.md","filePath":"blogs/CC/第一分编：通则（第一章：一般规定）（合同）.md"}'),r={name:"blogs/CC/diyifenbian：tongze（diyizhang：yibanguiding）（hetong）.md"};function n(_,a,l,d,h,s){return t(),i("div",null,[...a[0]||(a[0]=[o('<h3 id="第四百六十三条" tabindex="-1">第四百六十三条 <a class="header-anchor" href="#第四百六十三条" aria-label="Permalink to &quot;第四百六十三条&quot;">​</a></h3><p>本编调整因合同产生的民事关系。</p><h3 id="第四百六十四条" tabindex="-1">第四百六十四条 <a class="header-anchor" href="#第四百六十四条" aria-label="Permalink to &quot;第四百六十四条&quot;">​</a></h3><p>合同是民事主体之间设立、变更、终止民事法律关系的协议。 婚姻、收养、监护等有关身份关系的协议，适用有关该身份关系的法律规定；没有规定的，可以根据其性质参照适用本编规定。</p><h3 id="第四百六十五条" tabindex="-1">第四百六十五条 <a class="header-anchor" href="#第四百六十五条" aria-label="Permalink to &quot;第四百六十五条&quot;">​</a></h3><p>依法成立的合同，受法律保护。 依法成立的合同，仅对当事人具有法律约束力，但是法律另有规定的除外。</p><h3 id="第四百六十六条" tabindex="-1">第四百六十六条 <a class="header-anchor" href="#第四百六十六条" aria-label="Permalink to &quot;第四百六十六条&quot;">​</a></h3><p>当事人对合同条款的理解有争议的，应当依据本法第一百四十二条第一款的规定，确定争议条款的含义。 合同文本采用两种以上文字订立并约定具有同等效力的，对各文本使用的词句推定具有相同含义。各文本使用的词句不一致的，应当根据合同的相关条款、性质、目的以及诚信原则等予以解释。</p><h3 id="第四百六十七条" tabindex="-1">第四百六十七条 <a class="header-anchor" href="#第四百六十七条" aria-label="Permalink to &quot;第四百六十七条&quot;">​</a></h3><p>本法或者其他法律没有明文规定的合同，适用本编通则的规定，并可以参照适用本编或者其他法律最相类似合同的规定。 在中华人民共和国境内履行的中外合资经营企业合同、中外合作经营企业合同、中外合作勘探开发自然资源合同，适用中华人民共和国法律。</p><h3 id="第四百六十八条" tabindex="-1">第四百六十八条 <a class="header-anchor" href="#第四百六十八条" aria-label="Permalink to &quot;第四百六十八条&quot;">​</a></h3><p>非因合同产生的债权债务关系，适用有关该债权债务关系的法律规定；没有规定的，适用本编通则的有关规定，但是根据其性质不能适用的除外。</p>',12)])])}const b=e(r,[["render",n]]);export{p as __pageData,b as default};
